edema.","cues":"Sim LeaderProvide history chest pain and progressive shortness of breath\nIf prompted provide PMHx of HTN, pre-diabetes, cardiac FHx\n\nSim Nurse\nPrompt learner to consider analgesia\nProvide ECG only after complete history taking","sourceTrigger":"structured history and A-E completed, ECG provided, time elapsed","transition":null,"actions":[{"id":"stemi-1-0","text":"Introduce self and confirm patient identity","objective":"assessment","response":null},{"id":"stemi-1-1","text":"Systematic history including SOCRATES for chest pain","objective":"assessment","response":null},{"id":"stemi-1-2","text":"A-E Assessment","objective":"assessment","response":null},{"id":"stemi-1-3","text":"Requests ECG","objective":"assessment","response":null}]},{"id":"2","name":"Differential Diagnosis/Investigations","observations":{"rr":20,"spo2":95,"hr":100,"sbp":136,"dbp":78,"temp":37.2},"oxygen":"Room air","rhythm":null,"findings":"As above; elevated HR, down-trending BP.","cues":"Sim LeaderPatient to complain of pain and nausea\nBP down-trending, HR increasing\nQuery diagnosis - “Am I going to die?”\n\nSim Nurse\nProvide ECG when requested\nPrompt learner with patient discomfort\nPrompt learner for anti-emetic if sick\nAsk for most likely diagnosis/differential","sourceTrigger":"Identifies ACS, appropriate treatment prescribed, differential given, escalation, time elapsed","transition":null,"actions":[{"id":"stemi-2-0","text":"Interpretation of ECG","objective":"interpretation","response":null},{"id":"stemi-2-1","text":"Identifies anterior STEMI","objective":"interpretation","response":null},{"id":"stemi-2-2","text":"Prescribes appropriate ACS treatments","objective":"interpretation","response":null},{"id":"stemi-2-3","text":"Prescribe analgesia/anti-emetic if not done already","objective":"interpretation","response":null},{"id":"stemi-2-4","text":"Escalation to registrar/2222","objective":"interpretation","response":null}]},{"id":"3","name":"Patient Deterioration","observations":{"rr":28,"spo2":84,"hr":120,"sbp":116,"dbp":76,"temp":37.2},"oxygen":"Room air","rhythm":null,"findings":"Tachycardia, hypoxia, hypotension. Visibly breathless with bibasal crackles. ","cues":"Sim LeaderEscalate hypoxia and tachycardia\nReduce blood pressure\nPatient to become increasingly distressed\nDrop sats to 70s if O2 not commenced\n\nSim Nurse\nPrompt learner to recognise patient deterioration\nProvide CXR when requested\nProvide ABG when requested\nIf 2222 not called or alternative help sought – prompt learner that seems to be time critical emergency","sourceTrigger":"CXR requested, repeat A-E assessment underway, time elapsed, calls for senior support/2222","transition":null,"actions":[{"id":"stemi-3-0","text":"Recognise deterioration in patient","objective":"escalation","response":null},{"id":"stemi-3-1","text":"Further A-E Assessment","objective":"escalation","response":null},{"id":"stemi-3-2","text":"Commence O2 therapy","objective":"escalation","response":null},{"id":"stemi-3-3","text":"Requests ABG","objective":"escalation","response":null},{"id":"stemi-3-4","text":"Requests CXR","objective":"escalation","response":null},{"id":"stemi-3-5","text":"Updates ECG/commence cardiac monitoring","objective":"escalation","response":null},{"id":"stemi-3-6","text":"Escalates 2222 if not done already","objective":"escalation","response":null}]},{"id":"4","name":"Deterioration, Escalation, SBAR Handover","observations":{"rr":22,"spo2":96,"hr":102,"sbp":120,"dbp":74,"temp":37.2},"oxygen":"On oxygen; flow unspecified","rhythm":null,"findings":"Less breathless, normal sats on O2, ongoing bibasal crackles, HR and BP improving.","cues":"Sim LeaderTake on role of medical registrar arriving\nReceive SBAR handover\nPrompt for differential diagnosis\nPrompt for any missed investigations/interpretation\n\n\nSim Nurse\nReassure patient/acting in background","sourceTrigger":"Completed handover – scenario end","transition":null,"actions":[{"id":"stemi-4-0","text":"Identifies acute pulmonary oedema on CXR","objective":"handover","response":null},{"id":"stemi-4-1","text":"Identifies T1RF on ABG","objective":"handover","response":null},{"id":"stemi-4-2","text":"Suggests IV diuretic","objective":"handover","response":null},{"id":"stemi-4-3","text":"Deliver SBAR handover","objective":"handover","response":null},{"id":"stemi-4-4","text":"Offer likely diagnosis and plan","objective":"handover","response":null}]}],"investigations":[{"id":"ecg","name":"12-lead ECG","assetPath":null},{"id":"cxr","name":"Chest X-ray","assetPath":null},{"id":"abg","name":"ABG report","assetPath":null}],"review":["Rhythms, timers, transition combinations and treatment responses unset","No diagnostic investigation assets supplied","Original documents preserved in private source archive","Stage 3 labels hypotension at BP 116/76: clarify relative reduction versus intended target.","Source cue gates ECG release on complete history: preserved as source wording, not a software lock."],"source":"Original source files: 4-STEMI_PatientHx.docx, 3-STEMI-sim-checklist.docx"}'::jsonb) on conflict(id,version) do nothing;
insert into public.scenarios(id,data) values('ptx','{"id":"ptx","version":1,"title":"Tension pneumothorax","patient":"23-year-old man","briefing":"Abrupt left-sided pleuritic chest pain for two hours, pain 7/10 and shortness of breath.","history":"PATIENT HISTORYScenario 2 – Pneumothorax RPATIENT HISTORYScenario 2 – Pneumothorax R\nPATIENT HISTORY\nScenario 2 – Pneumothorax \nR\nPATIENT HISTORY\nScenario 2 – Pneumothorax \nR\n\n\nPresenting Complaint: \n23-year-old male\nSevere chest pain \n\nHistory of Presenting Complaint\nSudden onset pain 2 hours ago\nSharp and left sided with no radiation\nWorse on inspiration\nTried paracetamol without improvement\nPain 7/10\nWorried as now short of breath while talking, walking into ED, climbing stairs\n\nRelevant Additional History (if asked) \nFather had “connective tissue problem” and suddenly died when he was younger\nSemi-professional basketball player\n\nPMH \nNil\n\nMedications \nOTC Paracetamol\n\nAllergies \nNKDA\n\nSocial History \nNon-smoker\nWorks as a PE teacher\nDriver\nNo alcohol\n\n\n\n\n","preparation":"20-minute simulation and 20-minute debrief. Prepare actor/mannequin, monitor and locally reviewed investigation assets. Equipment details need faculty review.","objectives":[{"id":"assessment","text":"Perform a structured history and A-E assessment"},{"id":"interpretation","text":"Interpret investigations and form a differential"},{"id":"escalation","text":"Recognise deterioration and escalate appropriately"},{"id":"handover","text":"Communicate diagnosis and plan using SBAR"}],"stages":[{"id":"1","name":"A-E ASSESSMENT","observations":{"rr":20,"spo2":93,"hr":100,"sbp":123,"dbp":80,"temp":36.2},"oxygen":"Room air","rhythm":null,"findings":"Breathless, reduced AE and chest expansion on L side","cues":"Sim LeaderProvide history of acute onset chest pain and shortness of breath\nIf prompted give family history of ‘connective tissue disorder'', non-smoker, nil trauma.\n\nSim Nurse\nAsk for early differential diagnosis \nPrompt learner to consider analgesia","sourceTrigger":"completes history and initial A-E, provides differential diagnoses, requests CXR","transition":null,"actions":[{"id":"ptx-1-0","text":"Introduce self and confirm patient identity","objective":"assessment","response":null},{"id":"ptx-1-1","text":"Succinct history taking","objective":"assessment","response":null},{"id":"ptx-1-2","text":"A-E Assessment","objective":"assessment","response":null},{"id":"ptx-1-3","text":"Oxygen therapy","objective":"assessment","response":null},{"id":"ptx-1-4","text":"Requests CXR","objective":"assessment","response":null},{"id":"ptx-1-5","text":"Requests ABG","objective":"assessment","response":null},{"id":"ptx-1-6","text":"Requests ECG","objective":"assessment","response":null}]},{"id":"2","name":"Differential Diagnosis/Investigations","observations":{"rr":18,"spo2":96,"hr":100,"sbp":120,"dbp":70,"temp":36.4},"oxygen":"Oxygen at 4 L/min","rhythm":null,"findings":"Mildly breathless, sats stable on O2","cues":"Sim LeaderPatient to complain of discomfort\nAsks for diagnosis and plan\nDrop sats if no O2 therapy given\n\nSim Nurse\nProvide ECG when asked\nProvide ABG when asked","sourceTrigger":"Investigations complete/interpretation performed, differential given, time elapsed","transition":null,"actions":[{"id":"ptx-2-0","text":"Interpretation of T1RF on ABG","objective":"interpretation","response":null},{"id":"ptx-2-1","text":"Interpretation of ECG","objective":"interpretation","response":null},{"id":"ptx-2-2","text":"Differential diagnosis that includes PTX","objective":"interpretation","response":null},{"id":"ptx-2-3","text":"Prescribe analgesia/anti-emetic","objective":"interpretation","response":null}]},{"id":"3","name":"Patient Deterioration/Escalation","observations":{"rr":26,"spo2":80,"hr":130,"sbp":90,"dbp":60,"temp":36.3},"oxygen":"Oxygen at 4 L/min","rhythm":null,"findings":"Distressed, R tracheal deviation, no breath sounds on L side","cues":"Sim LeaderEscalate hypoxia and tachycardia, reduce blood pressure (improves to 94% on 15L)\nPatient to become increasingly distressed\nIf students commit to intervention – “Have you done this before doctor?”\n\nSim Nurse\nPrompt learner to recognise patient deterioration\nProvide CXR\nIf 2222 not called or alternative help sought – prompt learner that seems to be time critical emergency\nPrepares kit/model for decompression","sourceTrigger":"2222 call put out, repeat A-E assessment underway, commits to decompression, time elapsed","transition":null,"actions":[{"id":"ptx-3-0","text":"Recognise deterioration in patient","objective":"escalation","response":null},{"id":"ptx-3-1","text":"Further A-E Assessment","objective":"escalation","response":null},{"id":"ptx-3-2","text":"Call for immediate help: 2222","objective":"escalation","response":null},{"id":"ptx-3-3","text":"Recognises need for immediate needle decompression","objective":"escalation","response":null},{"id":"ptx-3-4","text":"Receives CXR – accurately interprets as tension PTX","objective":"escalation","response":null}]},{"id":"4","name":"SBAR Handover, intervention","observations":{"rr":30,"spo2":84,"hr":135,"sbp":85,"dbp":55,"temp":36.3},"oxygen":"Oxygen at 15 L/min","rhythm":null,"findings":"As above, increasing hypoxia and haemodynamic instability. Periarrest. ","cues":"Sim LeaderTake on role of medical registrar arriving\nReceive SBAR handover and differential\nPrompt for any missed investigations/interpretation\nInitiates/supervises decompression\n\n\nSim Nurse\nReassure patient/acting in background","sourceTrigger":"Completed handover and intervention – scenario end","transition":null,"actions":[{"id":"ptx-4-0","text":"Deliver SBAR handover","objective":"handover","response":null},{"id":"ptx-4-1","text":"Offers diagnosis of tension PTX","objective":"handover","response":null},{"id":"ptx-4-2","text":"Completes needle decompression under supervision of medical registrar","objective":"handover","response":null}]}],"investigations":[{"id":"ecg","name":"12-lead ECG","assetPath":null},{"id":"cxr","name":"Chest X-ray","assetPath":null},{"id":"abg","name":"ABG report","assetPath":null}],"review":["Rhythms, timers, transition combinations and treatment responses unset","No diagnostic investigation assets supplied","Original documents preserved in private source archive","Stage 3 faculty cue describes SpO2 improving to 94% on 15 L/min, while stage 4 profile is 84% on 15 L/min. Keep response and timing unset pending faculty review.","No post-decompression recovery profile is supplied. Urgent intervention is not gated by SBAR."],"source":"Original source files: PTX sim checklist.docx, PTx_PatientHx.docx"}'::jsonb) on conflict(id) do nothing;
